function App() {
  const [url, setUrl] = useState('/gallery');
  const [modalId, setModalId] = useState(null);
  const open = (id) => { setUrl('/photo/' + id); setModalId(id); };
  const refresh = () => setModalId(null); // hard refresh bypasses the intercept
  const back = () => { setUrl('/gallery'); setModalId(null); };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <div style={{ fontFamily: 'ui-monospace, monospace', marginBottom: 8 }}>URL: {url}</div>
      <div style={{ display: 'flex', gap: 8 }}>
        {[1, 2, 3].map(id => (
          <button key={id} onClick={() => open(id)}>Open photo {id}</button>
        ))}
      </div>
      {modalId != null ? (
        <div style={{ marginTop: 12, padding: 12, border: '2px solid #888', borderRadius: 8 }}>
          <b>Modal (intercepted):</b> photo {modalId}
          <div style={{ marginTop: 8 }}>
            <button onClick={refresh}>Simulate hard refresh</button>{' '}
            <button onClick={back}>Close</button>
          </div>
        </div>
      ) : url.startsWith('/photo/') ? (
        <div style={{ marginTop: 12 }}><b>Full page</b> for {url} (after refresh)</div>
      ) : (
        <div style={{ marginTop: 12 }}>Gallery grid</div>
      )}
    </div>
  );
}

