// Add app/dashboard/@modal/default.tsx:
//   export default function Default() { return null; }
// Now the slot renders nothing (instead of 404) when no modal matches.
function App() {
  const tree = [
    'app/dashboard/layout.tsx',
    'app/dashboard/page.tsx',
    'app/dashboard/@modal/(.)photo/[id]/page.tsx',
    'app/dashboard/@modal/default.tsx   // export default () => null',
  ];
  return <pre style={{ padding: 16, fontFamily: 'ui-monospace, monospace', fontSize: 12 }}>{tree.join('\n')}</pre>;
}

// app/(gallery)/layout.tsx — Server Component receiving the slot as a prop
export default function GalleryLayout({
  children,
  modal,
}: {
  children: React.ReactNode;
  modal: React.ReactNode;
}) {
  return (
    <section>
      {children}
      {modal}
    </section>
  );
}

// app/(gallery)/@modal/default.tsx — renders nothing when no modal matches
export default function Default() {
  return null;
}

// app/(gallery)/@modal/(.)photo/[id]/page.tsx — intercepts /photo/[id] into the slot
export default function PhotoModal({ params }: { params: { id: string } }) {
  return <dialog open>Photo {params.id} (modal)</dialog>;
}
